const std=@import("std");const K=@import("experimental/soil_root_kernel_diag.zig");const Fixture=struct{patch:usize,state:K.State,temperature:f64};
test "all preserved occupied cells under fixed eligibility probe"{const parsed=try std.json.parseFromSlice([]Fixture,std.testing.allocator,@embedFile("experimental/soil_actual_fixtures.json"),.{});defer parsed.deinit();var accepted:usize=0;var refused:usize=0;var flowing:usize=0;for(parsed.value)|f|for([_]f64{1,60,1440})|dt|{var p=K.Params{.dt=dt,.capacity=1,.infiltration_rate=1.0/1024.0,.conductance=1,.exposure=.{1,1,1,1},.temperature=f.temperature,.depth_m=0};for(f.state.cohorts,0..)|c,i|p.demand[i]=0.1*@max(0,c.biomass-c.support)*dt/86400;if(K.step(f.state,p))|r|{accepted+=1;var flow:f64=0;for(r.root_receipts,r.store_receipts)|a,b|flow+=a+b;if(flow>0)flowing+=1;std.debug.print("SOIL_ACTUAL patch={d} dt={d} accepted=true flow={d}\n",.{f.patch,dt,flow});}else{refused+=1;std.debug.print("SOIL_ACTUAL patch={d} dt={d} accepted=false\n",.{f.patch,dt});}};std.debug.print("SOIL_COVERAGE cells={d} cases={d} accepted={d} refused={d} positive_flow={d}\n",.{parsed.value.len,accepted+refused,accepted,refused,flowing});}
